import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, test } from "node:test";
import { detect, type Detection } from "../src/subset";

// Expected detection results for the fixtures in `test/fixtures/`, generated by
// `test/generate-fixtures.ts`. Each fixture is checked unminified and minified.

const DEFAULT: Detection = {
  fonts: ["outlined"],
  opsz: { min: 24, max: 24 },
  wght: { min: 400, max: 400 },
  grad: { min: 0, max: 0 },
  fill: { min: 0, max: 0 },
  symbols: ["home"],
};

const SHARED: Record<string, Detection> = {
  default: DEFAULT,
  "style-outlined": DEFAULT,
  "style-rounded": { ...DEFAULT, fonts: ["outlined", "rounded"] },
  "style-sharp": { ...DEFAULT, fonts: ["outlined", "sharp"] },
  "hover-fill": { ...DEFAULT, fill: { min: 0, max: 1 } },
  bold: { ...DEFAULT, wght: { min: 400, max: 700 } },
  "numeric-size": { ...DEFAULT, opsz: { min: 24, max: 32 } },
  // `.iconic { font-family: "Material Symbols Sharp" }` is not an icon style.
  iconic: DEFAULT,
  "five-digit-codepoint": { ...DEFAULT, symbols: ["2d_2", "home"] },
};

// The default fill is 1, and `icon-fill` sets it on every icon: the FILL axis is pinned to 1.
const FILL_DEFAULT: Detection = { ...DEFAULT, fill: { min: 1, max: 1 } };

const EXPECTED = {
  v3: {
    ...SHARED,
    // `theme.extend.icon.font.DEFAULT` = Rounded, `wght.DEFAULT` = 300
    "custom-defaults": {
      ...DEFAULT,
      fonts: ["rounded"],
      wght: { min: 300, max: 300 },
    },
    // `fill.DEFAULT` = 0.5 (minified `.5`), `grad.DEFAULT` = -25
    "fractional-defaults": {
      ...DEFAULT,
      grad: { min: -25, max: -25 },
      fill: { min: 0.5, max: 0.5 },
    },
    // `theme.extend.icon.fill.DEFAULT` = 1
    "fill-default": FILL_DEFAULT,
  },
  v4: {
    ...SHARED,
    // `--default-icon-font: var(--icon-font-rounded)`, `--icon-opsz-2xl: 48`,
    // `--icon-wght-heavy: 650`
    "custom-theme": {
      ...DEFAULT,
      fonts: ["rounded"],
      opsz: { min: 24, max: 48 },
      wght: { min: 400, max: 650 },
      symbols: ["2d_2", "home"],
    },
    // `--default-icon-*` with literal values instead of `var()` references
    "literal-defaults": {
      ...DEFAULT,
      fonts: ["rounded"],
      opsz: { min: 48, max: 48 },
      wght: { min: 300, max: 300 },
      grad: { min: 200, max: 200 },
      fill: { min: 1, max: 1 },
    },
    // `--default-icon-fill: 0.5` (minified `.5`), `--default-icon-grad: -25`,
    // `--default-icon-wght: 350.5`
    "fractional-defaults": {
      ...DEFAULT,
      wght: { min: 350.5, max: 350.5 },
      grad: { min: -25, max: -25 },
      fill: { min: 0.5, max: 0.5 },
    },
    // `--default-icon-fill: var(--icon-fill-fill)`
    "fill-default": FILL_DEFAULT,
  },
} satisfies Record<"v3" | "v4", Record<string, Detection>>;

function readFixture(version: string, name: string): string {
  return readFileSync(resolve(import.meta.dirname, "fixtures", version, name), "utf-8");
}

/** Sorts the lists so that the order of rules in the CSS doesn't matter. */
function normalize(detection: Detection): Detection {
  return {
    ...detection,
    fonts: [...detection.fonts].sort(),
    symbols: [...detection.symbols].sort(),
  };
}

for (const [version, fixtures] of Object.entries(EXPECTED)) {
  describe(`Tailwind ${version}`, () => {
    test("every fixture has an expected result", () => {
      const files = readdirSync(resolve(import.meta.dirname, "fixtures", version)).sort();
      const expected = Object.keys(fixtures).flatMap((name) => [`${name}.css`, `${name}.min.css`]);
      assert.deepEqual(files, expected.sort());
    });

    for (const [name, expected] of Object.entries(fixtures)) {
      for (const file of [`${name}.css`, `${name}.min.css`]) {
        test(file, () => {
          assert.deepEqual(normalize(detect(readFixture(version, file))), expected);
        });
      }
    }
  });
}

describe("defaults option", () => {
  const symbolsOnly = `:root { --icon-symbol-home: "\\e9b2"; }`;

  test("is used for the styles and axes that the CSS has no value for", () => {
    assert.deepEqual(detect(symbolsOnly), DEFAULT);
    assert.deepEqual(detect(symbolsOnly, { defaults: { font: "sharp", wght: 300, fill: 1 } }), {
      ...DEFAULT,
      fonts: ["sharp"],
      wght: { min: 300, max: 300 },
      fill: { min: 1, max: 1 },
    });
  });

  test("isn't added to the values in the CSS", () => {
    const defaults = { font: "sharp", opsz: 48, wght: 300, grad: 200, fill: 1 } as const;
    for (const version of ["v3", "v4"]) {
      assert.deepEqual(detect(readFixture(version, "default.min.css"), { defaults }), DEFAULT);
    }
  });
});
